head.script:
scwin.fireDbClick = function(id) {
    var node = WebSquare.wUnit.getDomById($p.id + id);
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.__isBackground = function() {
    var color = WebSquare.wUnit.getJq("#gridView1_cell_0_1").css("background-color");
    if (color.indexOf("rgb") < 0) {
        return color == "#fca73c";
    }
    return color == "rgb(252, 167, 60)";
}
scwin.setVal = function() {
    scwin.fireDbClick('gridView1_cell_0_0');
}
scwin.setSimulate1 = function() {
    WebSquare.wUnit.getJq('#gridView1_cell_0_0').simulate('keydown', {
        keyCode: 9,
        which: 9,
        key: 'TAB'
    });
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 name1항목의 첫번째 컬럼에 마우스를 더블클릭한다.
    //1. After running the sample file, double click on the first column of name1 item.
    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 선택할수 있는 리스트가 보여진다.
    //2. The value is checked.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#G_gridView1___checkcombobox_col1_itemTable').css('display')", "block");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 선택값 리스트에서 값을 선택하여 체크한다.
    //2. Select and check the values in the selection list.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_gridView1___checkcombobox_col1_itemTable_0_checkbox').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 값이 체크되어진다.
    //2. The value is checked.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('G_gridView1___checkcombobox_col1_itemTable_0_checkbox').checked", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. 2번상태에서 tab키를 누른다.
    //3. In the second state, press the tab key.
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. 선택한값이 입력되어지고 포커스는 다음항목의 값으로 이동되어진다.(이전에는 선택한값이 입력되어지지 않고 그대로 선택리스트로 있었음)
    //3. The selected value is entered and the focus is moved to the next item"s value (previously the selected value was not entered but it was in the selected list)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_0').innerText", "11");
    WebSquare.wUnit.addCommand("assert", "scwin.__isBackground()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 15-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
